// === Tab: mySketch ===
let particles = new Array(8192);
ArrayList<int> deadPixelsUnicoords = new ArrayList<int>();
boolean[][] deadPixelsMap;

let widt, heigh;
let wid, heig;

int[][] unicoord;

let black = color(0);
let white = color(255);
let blue = color(0, 128, 255);

////////////////////////////////////////////////////////////////////////////////////////////////////

function setup() {
  createCanvas(1024, 768);

	widt = width-1;
	heigh = height-1;

	wid = width-2;
	heig = height-2;

	unicoord = new Array(width)[height];
  let pixel = 0;
  for (y = 0; y < height; y++) {
    for (x = 0; x < width; x++) {
      unicoord[x][y] = pixel++;
    }
  }

	deadPixelsMap = new Array(width)[height];

	for (x = 0; x < width; x += int(random(16, 256))) {
		deadPixelsMap[x][heigh] = true;
	  deadPixelsUnicoords.add(unicoord[x][heigh]);
	}

	for (i = 0; i < particles.length; i++) {
		particles[i] = new Particle();
	}
}

////////////////////////////////////////////////////////////////////////////////////////////////////

function draw() {
	background(blue);
	loadPixels();

	for (i = 0; i < particles.length; i++) {
		particles[i].move();
		particles[i].checkForDeath();

		pixels[unicoord[particles[i].int_px][particles[i].int_py]] = white;
	}

	for (let deadPixelUnicoord of deadPixelsUnicoords) {
		pixels[deadPixelUnicoord] = black;
	}

  updatePixels();
}

////////////////////////////////////////////////////////////////////////////////////////////////////

class Particle {
	px, py, vx, vy;
  int_px, int_py;

  constructor() {
		px = random(1, wid);
		py = random(1, heig);

		int_px = int(px);
		int_py = int(py);
	}

	function move() {
		vx = vx * 0.98 + randomGaussian() * 0.01;
		vy = vy * 0.98 + randomGaussian() * 0.01 + 0.01;

		vx = constrain(vx, -1, 1);
		vy = constrain(vy, -1, 1);

		px += vx;
		py += vy;

		if (px < 1) {
			px = 1;
			vx = -vx;
		}
		else if (px > wid) {
			px = wid;
			vx = -vx
		}

		if (py < 1) {
			py = 1;
			vy = -vy;
		}
		else if (py > heigh) {
			px = random(1, wid);
			py = 1;
			vx = 0;
			vy = 0;
		}

		int_px = int(px);
		int_py = int(py);
	}

  function checkForDeath() {
		if (deadPixelsMap[int_px][int_py + 1] ||
				deadPixelsMap[int_px - 1][int_py + 1] ||
			  deadPixelsMap[int_px + 1][int_py + 1]) {

			deadPixelsMap[int_px][int_py] = true;
			deadPixelsUnicoords.add(unicoord[int_px][int_py]);

			px = random(1, wid);
		  py = 1;

			int_px = int(px);
		  int_py = int(py);

			vx = 0;
			vy = 0;
		}
  }
}

